style.css:
/* TOXIC LIPSTICK — Electropunk Global */
/* i really want this to be global */

:root {
  /* swap these colors if you want */
  --my-pink: #ff38bd;
  --my-green: #c6ff00;
  --my-black: #101010;
  --my-white: #f5f0df;
  --my-red: #ff3030;
}

/* dirty punk background */
html, body {
  background-color: var(--my-black) !important;
  color: var(--my-white) !important;
  font-family: "Courier New", monospace !important;
}

/* chaotic punk headings */
h1, h2, h3 {
  color: var(--my-pink) !important;
  font-family: Impact, "Arial Black", sans-serif !important;
  font-weight: 900 !important;
  text-transform: uppercase !important;
  letter-spacing: -1px !important;
  text-shadow: 2px 2px var(--my-green) !important;
}

/* radioactive links */
a {
  color: var(--my-green) !important;
  text-decoration: underline wavy var(--my-pink) !important;
}

a:hover {
  color: var(--my-pink) !important;
  background: var(--my-green) !important;
}

/* photocopy punk panels */
article, section, main {
  border-color: var(--my-pink) !important;
}

/* brutalist buttons */
button {
  background: var(--my-pink) !important;
  color: var(--my-black) !important;
  border: 2px solid var(--my-green) !important;
  border-radius: 0 !important;
  font-family: "Courier New", monospace !important;
  font-weight: 900 !important;
  text-transform: uppercase !important;
  box-shadow: 4px 4px 0 var(--my-green) !important;
}

/* harsh selection colors */
::selection {
  background: var(--my-green) !important;
  color: var(--my-black) !important;
}

/* messy image frames */
img {
  border-radius: 0 !important;
}

/* punk scrollbar */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-black) !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-pink) !important;
  border: 2px solid var(--my-green) !important;
}

/* radioactive text fields */
input, textarea, select {
  background: var(--my-black) !important;
  color: var(--my-green) !important;
  border: 2px solid var(--my-pink) !important;
  border-radius: 0 !important;
}
